import bisect

def find_the_distance_value(arr1, arr2, d):
    arr2_sorted = sorted(arr2)                     # sort once
    count = 0
    for x in arr1:
        idx = bisect.bisect_left(arr2_sorted, x - d)   # first candidate at least x - d
        if idx == len(arr2_sorted) or arr2_sorted[idx] > x + d:
            count += 1
    return count

