import java.util.*;

public class Main {
    static int findTheDistanceValue(int[] arr1, int[] arr2, int d) {
        int[] sorted2 = arr2.clone();
        Arrays.sort(sorted2);                            // sort once
        int count = 0;
        for (int x : arr1) {
            int idx = lowerBound(sorted2, x - d);            // first candidate at least x - d
            if (idx == sorted2.length || sorted2[idx] > x + d) count++;
        }
        return count;
    }

    static int lowerBound(int[] arr, int target) {
        int lo = 0, hi = arr.length;
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (arr[mid] < target) lo = mid + 1; else hi = mid;
        }
        return lo;
    }
}

