#include <bits/stdc++.h>
using namespace std;

int findTheDistanceValue(vector<int>& arr1, vector<int>& arr2, int d) {
    vector<int> sorted2 = arr2;
    sort(sorted2.begin(), sorted2.end());              // sort once
    int count = 0;
    for (int x : arr1) {
        auto it = lower_bound(sorted2.begin(), sorted2.end(), x - d);  // first candidate at least x - d
        if (it == sorted2.end() || *it > x + d) count++;
    }
    return count;
}
